          </p>
        ) : (
          <BoardWorkspace
            boardId={boardId}
            columns={listsWithCards}
            boardLabels={boardLabels}
            lists={lists.map((l) => ({ id: l.id, title: l.title }))}
          />
        )}
      </div>
    </AppShell>
  );
}

