    const token = db.invite[0].token as string;

    const { user: guest } = await signup("guest@b.co");
    loginAs(guest);
    const ok = await acceptPOST(bareReq("http://localhost/x"), tokenCtx(token));
    expect(ok.status).toBe(200);
